// Anti-aliased bitmap font format used by fonts.h (generated by tools/make_fonts.swift).
#pragma once
#include <stdint.h>

typedef struct { uint32_t offset; uint8_t w, h, adv; int8_t xo, yo; } AAGlyph;
typedef struct {
    const uint8_t *bmp;  // 4-bit alpha, row-major, high nibble first
    const AAGlyph *glyphs;
    uint8_t first, last, ascent, capH, lineH;
} AAFont;
